 static Boolean ControlTransfer(UInt64 context,Byte address,Byte endpoint,UsbSetupPacket* setup,Byte* buffer,UInt32 bytes,UInt32* transferred){Controller* c=(Controller*)(nuint)context;if(transferred!=null)*transferred=0;if(c==null||setup==null||endpoint!=0)return false;Slot* s=address==0?SlotById(c,c->PendingSlot):FindSlot(c,address);if(s==null)return false;if(setup->RequestType==0&&setup->Request==5){if(transferred!=null)*transferred=0;return true;}Boolean input=(setup->RequestType&0x80)!=0;KernelPhysicalAllocation bounce=default;Byte* dma=null;if(bytes!=0){if(!Buffer(bytes,out bounce,out dma))return false;if(!input&&buffer!=null)Copy(buffer,dma,bytes);}UInt64 setupValue=(UInt64)setup->RequestType|((UInt64)setup->Request<<8)|((UInt64)setup->Value<<16)|((UInt64)setup->Index<<32)|((UInt64)setup->Length<<48);UInt32 trt=bytes==0?0U:(input?3U:2U);if(!Enqueue(&s->Ep0,setupValue,0,8U,(2U<<10)|(1U<<6)|(trt<<16)|(bytes!=0?1U<<4:0U))){Release(bounce);return false;}if(bytes!=0&&!Enqueue(&s->Ep0,bounce.StartAddress,0,bytes,(3U<<10)|(input?1U<<16:0U)|(1U<<4))){Release(bounce);return false;}Boolean statusIn=bytes==0||!input;if(!Enqueue(&s->Ep0,0,0,0,(4U<<10)|(statusIn?1U<<16:0U)|(1U<<5))){Release(bounce);return false;}if(!PrepareTransferCompletion(c)){Release(bounce);return false;}RingDoorbell(c,s->SlotId,1);Boolean ok=WaitTransfer(c,s->SlotId,1,bytes,out UInt32 actual);if(ok&&bytes!=0&&input&&buffer!=null)Copy(dma,buffer,actual);if(ok&&input&&setup->Request==6&&(setup->Value>>8)==1&&actual>=8&&dma[7]!=s->Ep0Packet)ok=UpdateEp0(c,s,dma[7]);Release(bounce);if(transferred!=null)*transferred=actual;return ok;}
