 static Boolean DataTransfer(Controller* c,Byte address,Byte endpoint,Byte* buffer,UInt32 bytes,UInt32* transferred){if(transferred!=null)*transferred=0;if(c==null||buffer==null||bytes==0||bytes>4096)return false;Slot* s=FindSlot(c,address);if(s==null)return false;Byte dci=Dci(endpoint);Endpoint* e=FindEndpoint(c,s->SlotId,dci);if(e==null)return false;UInt64 trace=0UL;fixed(UInt64* p=&_diagnosticTransfers){UInt64 previous=0UL;Native.AtomicFetchAdd64(p,1UL,&previous);trace=previous+1UL;}if(trace<=64UL){Native.WritePort8(0xE9,(Byte)'Y');Native.WritePort8(0xE9,(Byte)trace);Native.WritePort8(0xE9,s->SlotId);Native.WritePort8(0xE9,dci);}Boolean input=(endpoint&0x80)!=0;if(!Buffer(bytes,out KernelPhysicalAllocation bounce,out Byte* dma)){if(trace<=64UL)Native.WritePort8(0xE9,(Byte)'1');return false;}if(!input)Copy(buffer,dma,bytes);if(!Enqueue(&e->Ring,bounce.StartAddress,0,bytes,(1U<<10)|(1U<<2)|(1U<<5))){Release(bounce);if(trace<=64UL)Native.WritePort8(0xE9,(Byte)'2');return false;}if(!PrepareTransferCompletion(c)){Release(bounce);if(trace<=64UL)Native.WritePort8(0xE9,(Byte)'3');return false;}TraceTransferState(c,0x30,s->SlotId,dci);RingDoorbell(c,s->SlotId,dci);if(trace<=64UL)Native.WritePort8(0xE9,(Byte)'B');TraceTransferState(c,0x31,s->SlotId,dci);Boolean ok=WaitTransfer(c,s->SlotId,dci,bytes,out UInt32 actual);TraceTransferState(c,ok?(Byte)0x32:(Byte)0x3F,s->SlotId,dci);if(trace<=64UL){Native.WritePort8(0xE9,ok?(Byte)'R':(Byte)'E');Native.WritePort8(0xE9,(Byte)actual);}if(ok&&input)Copy(dma,buffer,actual);Release(bounce);if(transferred!=null)*transferred=actual;return ok;}
