 static void BuildInput(Controller* c,Slot* s,Byte addDci,Endpoint* e){Byte* input=Direct(s->Input);Clear(input,4096);UInt32* icc=(UInt32*)input;UInt32 flags=1U;if(addDci!=0)flags|=1U<<addDci;icc[1]=flags;UInt32* slot=(UInt32*)(input+c->ContextSize);slot[0]=(s->Route&0xFFFFFU)|((UInt32)s->SpeedId<<20)|((UInt32)s->MultiTt<<25)|(s->HubPorts!=0?1U<<26:0U)|((UInt32)s->ContextEntries<<27);slot[1]=((UInt32)s->RootPort<<16)|((UInt32)s->HubPorts<<24);if(s->TtPort!=0)slot[2]=(UInt32)s->ParentSlot|((UInt32)s->TtPort<<8);if(addDci==1){UInt32* ep=(UInt32*)(input+(UInt32)c->ContextSize*2U);BuildEndpointContext(ep,4,s->Ep0Packet,s->Ep0.Memory.StartAddress,0,8,0U);}else if(e!=null){UInt32* ep=(UInt32*)(input+(UInt32)c->ContextSize*(UInt32)(e->Dci+1));UsbTransferType transferType=(UsbTransferType)e->Type;Byte type=EndpointType(e->Address,transferType);UInt32 maxEsitPayload=(transferType==UsbTransferType.Interrupt||transferType==UsbTransferType.Isochronous)?(UInt32)e->MaxPacket:0U;BuildEndpointContext(ep,type,e->MaxPacket,e->Ring.Memory.StartAddress,Interval(s->SpeedId,transferType,e->Interval),e->MaxPacket,maxEsitPayload);}}
